<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { Plus, Pencil, Trash2, X } from 'lucide-vue-next';
import FlockFormFields from '@/components/flocks/FlockFormFields.vue';
import { emptyFlock, flockPayload } from '@/composables/flockUtils';
import { flockApi, houseApi } from '@/services/api';
import { useAuthStore } from '@/stores/authStore';
import { useModalStore } from '@/stores/modalStore';
const auth=useAuthStore(),route=useRoute(),router=useRouter(),modal=useModalStore();
const rows=ref([]),loading=ref(false),error=ref(''),busy=ref(false),formError=ref(''),editing=ref(null),deleting=ref(null);
const editDialog=ref(null),deleteDialog=ref(null),form=ref(emptyFlock()),houses=ref([]),breeds=ref([]);
const canManage=computed(()=>auth.isSuperAdmin||auth.isFarmAdmin||auth.isFarmStaff);
const canDelete=computed(()=>auth.isSuperAdmin||auth.isFarmAdmin);
const statuses={ACTIVE:'ปกติ',BELOW_STANDARD:'ต่ำกว่ามาตรฐาน',NEAR_RETIRE:'ใกล้ปลดระวาง',PULLET:'ไก่รุ่น',RETIRED:'ปลดระวางแล้ว'};
const number=(n,d=0)=>n==null?'—':new Intl.NumberFormat('th-TH',{maximumFractionDigits:d}).format(n);
const percentage=n=>n==null?'—':`${number(n,1)}%`;
let request=0;
async function load(){const id=++request;if(!auth.isAuthenticated){rows.value=[];loading.value=false;return;}loading.value=true;error.value='';try{const {data}=await flockApi.list(auth.isSuperAdmin?{farmId:auth.effectiveFarmId}:{});if(id===request)rows.value=data;}catch(e){if(id===request)error.value=e.response?.data?.message||'โหลดข้อมูลฝูงไก่ไม่สำเร็จ';}finally{if(id===request)loading.value=false;}}
async function edit(flock){
  if(!canManage.value||busy.value)return;
  busy.value=true;error.value='';formError.value='';
  try{const [h,b]=await Promise.all([houseApi.list(auth.isSuperAdmin?{farmId:auth.effectiveFarmId}:{}),flockApi.breeds()]);
    const occupied=new Set(rows.value.filter(x=>x.flockId!==flock.flockId&&x.status!=='RETIRED').map(x=>x.houseId));
    houses.value=h.data.filter(x=>!occupied.has(x.houseId)&&(x.status==='ACTIVE'||x.houseId===flock.houseId));breeds.value=b.data;
    form.value={...emptyFlock(),...flock,supplier:flock.supplier||'',healthCertificate:flock.healthCertificate||'',vaccinated:flock.vaccinated??''};editing.value=flock;
    await nextTick();editDialog.value.showModal();
  }catch(e){error.value=e.response?.data?.message||'โหลดข้อมูลสำหรับแก้ไขไม่สำเร็จ';}finally{busy.value=false;}
}
function closeEdit(){if(!busy.value){editDialog.value?.close();editing.value=null;}}
async function save(){if(busy.value)return;busy.value=true;formError.value='';try{await flockApi.update(editing.value.flockId,flockPayload(form.value));editDialog.value.close();editing.value=null;await load();modal.openSuccess({title:'แก้ไขสำเร็จ',message:'แก้ไขข้อมูลฝูงไก่แล้ว'});}catch(e){formError.value=e.response?.data?.message||'บันทึกไม่สำเร็จ';}finally{busy.value=false;}}
async function confirmDelete(flock){if(!canDelete.value)return;deleting.value=flock;formError.value='';await nextTick();deleteDialog.value.showModal();}
function closeDelete(){if(!busy.value){deleteDialog.value?.close();deleting.value=null;}}
async function remove(){if(busy.value||!canDelete.value)return;busy.value=true;formError.value='';try{await flockApi.remove(deleting.value.flockId);deleteDialog.value.close();deleting.value=null;await load();modal.openSuccess({title:'ลบสำเร็จ',message:'ลบข้อมูลฝูงไก่แล้ว'});}catch(e){formError.value=e.response?.data?.message||'ลบข้อมูลไม่สำเร็จ';}finally{busy.value=false;}}
watch(()=>auth.effectiveFarmId,load);onMounted(load);onBeforeUnmount(()=>request++);
</script>
<template><section class="flocks-page"><header><div><h1>ข้อมูลฝูงไก่</h1><p>ติดตามอายุ จำนวน และผลผลิตของฝูงไก่ในฟาร์ม</p></div><button v-if="canManage" class="primary" @click="router.push({name:'farm-flocks-new',query:route.query})"><Plus :size="17" />รับฝูงใหม่</button></header><p v-if="error" class="error" role="alert">{{ error }} <button @click="load">ลองใหม่</button></p><div class="table-wrap" :aria-busy="loading"><table><thead><tr><th>ฝูง</th><th>โรงเรือน</th><th>อายุ</th><th>จำนวน<br />ปัจจุบัน</th><th>ตาย<br />สะสม</th><th>Hen-day</th><th>น้ำหนักไข่</th><th>อาหารต่อตัว<br />ต่อวัน</th><th>สถานะ</th><th v-if="canManage">จัดการ</th></tr></thead><tbody><tr v-if="loading"><td :colspan="canManage?10:9" class="empty">กำลังโหลดข้อมูล…</td></tr><tr v-else-if="!rows.length"><td :colspan="canManage?10:9" class="empty">{{ error?'โหลดข้อมูลไม่สำเร็จ':'ยังไม่มีข้อมูลฝูงไก่' }}</td></tr><tr v-for="flock in loading?[]:rows" :key="flock.flockId"><td><strong>{{ flock.flockCode }}</strong><span>{{ flock.breedName }}</span></td><td>{{ flock.houseName }}</td><td>{{ number(flock.ageWeeks) }}<span>สัปดาห์</span></td><td><strong>{{ number(flock.currentCount) }}</strong><span>จากที่รับ {{ number(flock.initialCount) }}</span></td><td>{{ percentage(flock.mortalityPercent) }}</td><td><strong>{{ percentage(flock.henDayPercent) }}</strong></td><td>{{ number(flock.eggWeightG,1) }}<span v-if="flock.eggWeightG!=null">กรัม</span></td><td>{{ number(flock.feedGramsPerBird,1) }}<span v-if="flock.feedGramsPerBird!=null">กรัม</span></td><td><span class="badge" :class="{warning:['BELOW_STANDARD','NEAR_RETIRE'].includes(flock.status),retired:flock.status==='RETIRED'}">{{ statuses[flock.status]||flock.status }}</span></td><td v-if="canManage"><div class="actions"><button class="icon-button" :aria-label="`แก้ไข ${flock.flockCode}`" :disabled="busy" @click="edit(flock)"><Pencil :size="15" /></button><button v-if="canDelete" class="icon-button" :aria-label="`ลบ ${flock.flockCode}`" :disabled="busy" @click="confirmDelete(flock)"><Trash2 :size="15" /></button></div></td></tr></tbody></table></div><p class="metric-note">— หมายถึงยังไม่มีข้อมูล • Hen-day และอาหารต่อตัวคำนวณจากบันทึกประจำวันที่มีจำนวนไก่มีชีวิตในวันเดียวกัน</p>
<Teleport to="body"><dialog ref="editDialog" class="flock-drawer" aria-labelledby="flock-edit-title" @cancel.prevent="closeEdit"><form @submit.prevent="save"><header><div><h2 id="flock-edit-title">แก้ไขข้อมูลฝูงไก่</h2><p>{{ editing?.flockCode }}</p></div><button class="icon-button" type="button" aria-label="ปิด" :disabled="busy" @click="closeEdit"><X :size="18" /></button></header><div class="drawer-body"><FlockFormFields v-model="form" :houses="houses" :breeds="breeds" :disabled="busy" /><p v-if="formError" role="alert" class="error">{{ formError }}</p></div><footer><button class="secondary" type="button" :disabled="busy" @click="closeEdit">ยกเลิก</button><button class="primary" :disabled="busy">{{ busy?'กำลังบันทึก…':'บันทึก' }}</button></footer></form></dialog><dialog ref="deleteDialog" class="delete-dialog" aria-labelledby="flock-delete-title" @cancel.prevent="closeDelete"><div class="delete-icon"><Trash2 :size="28" /></div><h2 id="flock-delete-title">ลบข้อมูลฝูงไก่นี้ใช่ไหม?</h2><p>{{ deleting?.flockCode }}</p><p>ฝูงนี้จะถูกนำออกจากรายการ โดยเก็บประวัติบันทึกเดิมไว้</p><p v-if="formError" class="error" role="alert">{{ formError }}</p><div class="confirm-actions"><button class="secondary" :disabled="busy" @click="closeDelete">ยกเลิก</button><button class="danger" :disabled="busy" @click="remove">{{ busy?'กำลังลบ…':'ยืนยัน' }}</button></div></dialog></Teleport>
</section></template>
<style scoped>
.flocks-page{max-width:1500px;margin:auto;color:#293823}header{display:flex;justify-content:space-between;align-items:center;gap:20px;margin:8px 0 25px}h1{font-size:26px;font-weight:800;margin:0 0 8px}h2{font-size:20px;font-weight:800;margin:0}header p{font-size:12px;color:#8a8578;margin:0}.primary,.secondary,.danger{display:inline-flex;align-items:center;justify-content:center;gap:7px;padding:11px 17px;border-radius:11px;font:inherit;font-size:12px;font-weight:700;cursor:pointer;border:1px solid #e1d8c7}.primary{background:#f6d390;border-color:#f6d390;color:#293823}.secondary{background:#faf7f0;color:#293823}.danger{background:#cb4545;border-color:#cb4545;color:white}button:disabled{opacity:.5;cursor:wait}.table-wrap{background:white;border:1px solid #e5ddce;border-radius:18px;overflow-x:auto}table{width:100%;border-collapse:collapse;text-align:left;font-size:14px;min-width:1080px}th{background:#faf8f3;color:#8a8579;font-size:13px;font-weight:500;padding:18px 18px;line-height:1.6}td{padding:24px 18px;border-top:1px solid #f2ece0;vertical-align:middle;line-height:1.6}td>span:not(.badge){display:block;margin-top:4px;font-size:13px}td:first-child{max-width:180px;overflow-wrap:anywhere}.badge{display:inline-block;border-radius:20px;padding:5px 11px;background:#e0eed5;color:#4b793d;font-size:12px;white-space:nowrap}.badge.warning{background:#f8e0bf;color:#ae6d24}.badge.retired{background:#e9e6df;color:#7e796e}.actions{display:flex;gap:7px}.icon-button{padding:8px;border:1px solid #e4d9bc;border-radius:7px;background:#faf6eb;color:#7b735d;display:inline-flex;cursor:pointer}.empty{text-align:center;color:#8a8578;padding:45px}.metric-note{font-size:12px;color:#92907f;margin-top:15px}.error{background:#fff0e9;color:#a2352c;border:1px solid #efc7bc;border-radius:10px;padding:13px;font-size:13px}.error button{color:inherit;background:transparent;border:0;text-decoration:underline;cursor:pointer}.flock-drawer{position:fixed;inset:0 0 0 auto;margin:0;padding:0;width:min(560px,100vw);max-width:100vw;height:100dvh;max-height:100dvh;border:0;background:white;color:#293823;box-shadow:-12px 0 30px #26311b26}.flock-drawer form{display:flex;flex-direction:column;height:100%}.flock-drawer header{padding:25px;margin:0}.flock-drawer header p{margin-top:7px}.drawer-body{padding:5px 25px 25px;overflow:auto;flex:1}.flock-drawer footer{display:flex;justify-content:flex-end;gap:12px;padding:18px 25px;border-top:1px solid #ece4d6}.delete-dialog{position:fixed;inset:0;margin:auto;width:380px;max-width:calc(100vw - 35px);max-height:calc(100dvh - 35px);overflow:auto;box-sizing:border-box;background:#faf7f2;border:1px solid #e8dfce;border-radius:25px;padding:30px;text-align:center;color:#293823;box-shadow:0 20px 35px #29311c33}.flock-drawer::backdrop,.delete-dialog::backdrop{background:#f7f2e5b8}.delete-icon{display:grid;place-items:center;width:70px;height:70px;background:#fce5df;color:#b83e2b;border-radius:50%;margin:0 auto 20px}.delete-dialog p{font-size:13px;color:#8a8578;line-height:1.7}.confirm-actions{display:flex;gap:12px;margin-top:25px}.confirm-actions button{flex:1}button:focus-visible{outline:2px solid #c9973f;outline-offset:3px}@media(max-width:650px){header{align-items:flex-start;flex-direction:column}.flock-drawer header{flex-direction:row}h1{font-size:22px}}
</style>
